    LogicalKeyboardKey.arrowLeft => CruftFreeTreeKey.left,
    LogicalKeyboardKey.home => CruftFreeTreeKey.home,
    LogicalKeyboardKey.end => CruftFreeTreeKey.end,
    LogicalKeyboardKey.enter || LogicalKeyboardKey.numpadEnter => CruftFreeTreeKey.enter,
    LogicalKeyboardKey.space => CruftFreeTreeKey.space,
